from __future__ import annotations

import numpy as np

from neural_thickets.types import ExperimentContract, PerturbationSpec

PAPER_POPULATION_SIZE = 5_000
PAPER_POPULATION_SEED = 42
PAPER_SIGMA_LADDER = (0.0005, 0.001, 0.002)


def paper_population(
    size: int = PAPER_POPULATION_SIZE,
    *,
    population_size: int = PAPER_POPULATION_SIZE,
    seed: int = PAPER_POPULATION_SEED,
    sigmas: tuple[float, ...] = PAPER_SIGMA_LADDER,
) -> tuple[PerturbationSpec, ...]:
    """Return the exact population generated by the original RandOpt driver.

    The full population is drawn before slicing. NumPy choice without replacement
    is not prefix-stable when its requested size changes, so drawing only ``size``
    seeds would produce a different experiment.
    """

    assert 0 < size <= population_size
    assert sigmas and all(sigma > 0 for sigma in sigmas)
    rng = np.random.default_rng(seed)
    seeds = rng.choice(2**31, size=population_size, replace=False)
    scales = rng.choice(sigmas, size=population_size)
    return tuple(
        PerturbationSpec(index=index, seed=int(seeds[index]), sigma=float(scales[index]))
        for index in range(size)
    )


def contract_population(contract: ExperimentContract) -> tuple[PerturbationSpec, ...]:
    assert contract.population_size is not None
    assert contract.population_draw_size is not None
    assert contract.population_seed is not None
    candidates = paper_population(
        contract.population_size,
        population_size=contract.population_draw_size,
        seed=contract.population_seed,
        sigmas=contract.sigma_ladder,
    )
    if contract.candidate_indices:
        lookup = {candidate.index: candidate for candidate in candidates}
        return tuple(lookup[index] for index in contract.candidate_indices)
    if contract.candidate_filter_sigma is not None:
        candidates = tuple(
            candidate
            for candidate in candidates
            if candidate.sigma == contract.candidate_filter_sigma
        )
    if contract.candidate_limit is not None:
        candidates = candidates[: contract.candidate_limit]
    assert candidates
    return candidates

